// The stamps site's Worker (wrangler.jsonc, generated by scripts/gen-wrangler.ts): the built page (dist/) as static
// assets, served with the security headers of src/csp.ts on every response, as the hosted demo's Worker does
// (apps/demo/worker/index.ts). It runs before the assets binding on every request (`run_worker_first`), so it alone
// decides what exists:
//
// - `/` and `/p/<account_id>` (src/routes.ts: a strictly valid id) are dist/index.html, with the page CSP;
// - every other path is a static asset (the hashed bundle, the fonts, the favicon), never an HTML file;
// - only GET and HEAD, only on STAMPS_ORIGIN (a preview or other hostname gets 404), and no cookies.
//
// Without its vars it serves nothing (503): the page must never go out without its CSP.
import { NON_PAGE_CSP, securityHeaders } from '../src/csp.ts';
import { parseRoute } from '../src/routes.ts';

export interface AssetsBinding {
  fetch(request: Request): Promise<Response>;
}

export interface StampsWorkerEnv {
  /** The site's origin (`https://hana-id-stamps-<env>.<subdomain>.workers.dev`): the only one it answers on. */
  STAMPS_ORIGIN?: string;
  /** The page's Content-Security-Policy (src/csp.ts pageCsp). */
  CSP?: string;
  ASSETS: AssetsBinding;
}

/** Hashed bundle files (Vite's `assets/<name>-<hash>.<ext>`) never change under one name. */
const IMMUTABLE = /^\/assets\/[\w.-]+-[\w-]{8,}\.(?:js|css|woff2)$/u;

function plain(status: number, text: string, head: boolean, extra: Record<string, string> = {}): Response {
  return new Response(head ? null : `${text}\n`, {
    status,
    headers: { ...securityHeaders(NON_PAGE_CSP), 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'no-store', ...extra },
  });
}

/** `res` with the security headers set (and any cookie dropped), keeping its body and content type. */
function withHeaders(res: Response, csp: string, cacheControl: string, head: boolean): Response {
  const headers = new Headers();
  const type = res.headers.get('content-type');
  if (type) headers.set('content-type', type);
  for (const k of ['etag', 'last-modified', 'content-length']) {
    const v = res.headers.get(k);
    if (v) headers.set(k, v);
  }
  for (const [k, v] of Object.entries(securityHeaders(csp))) headers.set(k, v);
  headers.set('cache-control', cacheControl);
  return new Response(head || res.status === 304 ? null : res.body, { status: res.status, headers });
}

/** The request's conditional headers, so the assets binding can answer 304. */
function conditional(request: Request): Headers {
  const h = new Headers();
  for (const k of ['if-none-match', 'if-modified-since']) {
    const v = request.headers.get(k);
    if (v) h.set(k, v);
  }
  return h;
}

export async function handleStamps(request: Request, env: StampsWorkerEnv): Promise<Response> {
  const head = request.method === 'HEAD';
  if (!env.CSP || !env.STAMPS_ORIGIN) return plain(503, 'Not configured', head);
  const url = new URL(request.url);
  if (url.origin !== env.STAMPS_ORIGIN) return plain(404, 'Not found', head);
  if (request.method !== 'GET' && !head) return plain(405, 'Method not allowed', head, { allow: 'GET, HEAD' });

  if (url.pathname === '/' || url.pathname.startsWith('/p/')) {
    if (parseRoute(url.pathname).kind === 'not_found') return plain(404, 'No such passport', head);
    const page = await env.ASSETS.fetch(new Request(new URL('/index.html', url.origin), { method: 'GET' }));
    if (page.status !== 200) {
      await page.body?.cancel();
      return plain(503, 'Page missing', head);
    }
    if (head) await page.body?.cancel();
    return withHeaders(page, env.CSP, 'no-cache', head);
  }
  // Pages exist only on their routes, with their headers.
  if (url.pathname.toLowerCase().endsWith('.html')) return plain(404, 'Not found', head);
  const asset = await env.ASSETS.fetch(new Request(url, { method: 'GET', headers: conditional(request) }));
  if ((asset.status !== 200 && asset.status !== 304) || /^\s*text\/html\b/iu.test(asset.headers.get('content-type') ?? '')) {
    await asset.body?.cancel();
    return plain(404, 'Not found', head);
  }
  if (head) await asset.body?.cancel();
  return withHeaders(asset, NON_PAGE_CSP, IMMUTABLE.test(url.pathname) ? 'public, max-age=31536000, immutable' : 'public, max-age=300', head);
}

export default {
  fetch: (request: Request, env: StampsWorkerEnv): Promise<Response> => handleStamps(request, env),
};
